            final value: spam
        '''

print("Format repr (first 200):", repr(fmt[:200]))
print()
print("Data repr (first 200):", repr(data[:200]))
print()

# Check if they match at the critical part
fmt_part = fmt.split('non-whitespace:')[1][:20]
data_part = data.split('non-whitespace:')[1][:20]
print("Format non-whitespace part:", repr(fmt_part))
print("Data non-whitespace part:", repr(data_part))
